:isDigit)},label={Text("شناسه ۱۶ رقمی صیادی *")},modifier=Modifier.fillMaxWidth());OutlinedTextField(serial,{serial=Digits.normalize(it).filter(Char::isDigit)},label={Text("شماره سریال/سری چک")},modifier=Modifier.fillMaxWidth());OutlinedTextField(chequeAccount,{chequeAccount=Digits.normalize(it)},label={Text("شماره حساب چک")},modifier=Modifier.fillMaxWidth());OutlinedTextField(chequeIban,{chequeIban=it.uppercase()},label={Text("شماره شبا")},modifier=Modifier.fillMaxWidth());Text("تاریخ سررسید *");PersianDateField(due,{due=it});Button({scope.launch{vm.repo.db.checkDao().insert(CheckEntity(direction=direction,amountRial=Money.inputToRial(amount,settings.moneyUnit)?:0,counterparty=party,bankName=bank,sayadId=sayad,serialNumber=serial,issuedAt=System.currentTimeMillis(),dueAt=due.startOfDayMillis(),reminderAt=null,imagePath=imagePath,issuerName=issuer,receiverName=receiver,nationalId=nationalId,chequeAccountNumber=chequeAccount,chequeIban=chequeIban));val checkNumber=sayad.ifBlank{serial};val dueReminderAt=due.startOfDayMillis()+9*60*60*1000L;val beforeReminderAt=due.plusDays(-1).startOfDayMillis()+9*60*60*1000L;val reminderNote="چک ${if(received)"دریافتی" else "صادرشده"} شماره $checkNumber — طرف حساب: $party";val beforeId=vm.repo.db.reminderDao().insert(ReminderEntity(title="یادآوری چک؛ یک روز مانده به سررسید",category="چک",note=reminderNote,nextAt=beforeReminderAt));val dueId=vm.repo.db.reminderDao().insert(ReminderEntity(title="موعد چک",category="چک",note=reminderNote,nextAt=dueReminderAt));LifeReminderWorker.schedule(context,beforeId,beforeReminderAt);LifeReminderWorker.schedule(context,dueId,dueReminderAt);showSavedMessage(context,"چک");onDone()}},enabled=party.isNotBlank()&&(Money.inputToRial(amount,settings.moneyUnit)?:0)>0&&sayad.length==16,modifier=Modifier.fillMaxWidth(),border=BorderStroke(1.5.dp,accent)){Text(if(received)"ثبت چک دریافت‌شده و یادآور" else "ثبت چک صادرشده و یادآور")}}
